#!/usr/bin/env bash
# Compile and upload the XRAY firmware. Reads Wi-Fi credentials from xray/.env.
# Usage: ./flash.sh [serial-port]   (auto-detects a USB serial port if omitted)
set -euo pipefail
cd "$(dirname "$0")"

[ -f .env ] || { echo "Missing xray/.env (copy .env.example)"; exit 1; }
set -a; source .env; set +a

cat > firmware/xray/secrets.h <<EOF
// Generated by flash.sh from .env. Do not commit.
#define WIFI_SSID "${WIFI_SSID}"
#define WIFI_PASS "${WIFI_PASS}"
EOF

PORT="${1:-$(ls /dev/cu.usbserial-* /dev/cu.wchusbserial* /dev/cu.SLAB_USBtoUART* 2>/dev/null | head -1 || true)}"
[ -n "$PORT" ] || { echo "No ESP32 serial port found"; exit 1; }

FQBN=esp32:esp32:esp32
arduino-cli compile --fqbn "$FQBN" firmware/xray
arduino-cli upload --fqbn "$FQBN" -p "$PORT" firmware/xray
echo "Flashed $PORT. Run 'npm start' in xray/ to open the visualizer."
